{
  "bioavailability_prediction": "low",
  "claims": [
    {
      "card_ids": ["C26"],
      "claim": "Acamprosate, a small highly polar and ionized molecule with poor permeability, has an absolute oral bioavailability of approximately 11% in humans under fasting conditions, supporting low F for similarly polar/ionized acids.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C05"],
      "claim": "Octreotide, a cyclic peptide, has an absolute oral bioavailability of only 0.6% in healthy volunteers, supporting very low oral F for polar cyclic peptide-like structures.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C07"],
      "claim": "Colistin, a cyclic peptide with multiple polar/ionizable groups, has low and virtually negligible oral bioavailability, supporting low F for the query's polar cyclic peptide-like scaffold.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C24"],
      "claim": "Microcystin-LR, a cyclic peptide, is reported to have low oral bioavailability in humans, further supporting low F for polar cyclic peptide-like molecules.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C18"],
      "claim": "Monomethyl fumarate has high oral bioavailability (90-95%), but it is a small lipophilic ester rather than a fully ionized diacid, so this high-F evidence has limited transferability to the query.",
      "evidence_role": "contradictory"
    },
    {
      "card_ids": ["C13"],
      "claim": "L-arginine shows about 70% oral bioavailability, but this depends on active amino acid transport that the query molecule lacks, making this high-F evidence weakly transferable.",
      "evidence_role": "contradictory"
    }
  ],
  "confidence": "moderate",
  "decision_summary": "The query is a highly polar, fully ionized dicarboxylic acid cyclic dipeptide with high TPSA and multiple HBD/HBA groups, properties strongly associated with poor passive permeability. The most relevant experimental analogues—acamprosate, octreotide, colistin, and microcystin-LR—all show low oral bioavailability. High-F analogues rely on active transport or lipophilic ester character not present in the query. Therefore, oral bioavailability below 20% is better supported.",
  "evidence_gaps": [
    "No direct experimental bioavailability or permeability data exist for the query molecule.",
    "No data on possible active uptake, efflux, or transporter-mediated absorption are available.",
    "No formulation or prodrug strategies were assessed.",
    "Morgan similarities to evidence molecules are low, limiting quantitative transferability."
  ],
  "new_evidence_assessment": [],
  "revision_action": "initial"
}

